/* Classroom terminal wiring and RFID memory model, without physical I/O. */
(function(root){'use strict';const cp=x=>JSON.parse(JSON.stringify(x));
const pins=[{id:'PS.+',x:80,y:90,kind:'24V',label:'电源 +24V'},{id:'PS.-',x:80,y:135,kind:'GND',label:'电源 GND'},{id:'GW.A',x:80,y:250,kind:'A',label:'网关 RS485 A'},{id:'GW.B',x:80,y:295,kind:'B',label:'网关 RS485 B'},{id:'S.V',x:540,y:90,kind:'24V',label:'传感器 V+'},{id:'S.G',x:540,y:135,kind:'GND',label:'传感器 GND'},{id:'S.A',x:540,y:250,kind:'A',label:'传感器 RS485 A'},{id:'S.B',x:540,y:295,kind:'B',label:'传感器 RS485 B'}];
const expected=[['PS.+','S.V'],['PS.-','S.G'],['GW.A','S.A'],['GW.B','S.B']];const key=(a,b)=>[a,b].sort().join('|');
function validate(wires){if(!Array.isArray(wires)||wires.length>20)throw Error('接线记录无效');const errors=[],seen=new Set();for(const w of wires){const a=pins.find(p=>p.id===w.a),b=pins.find(p=>p.id===w.b);if(!a||!b){errors.push('未知端子');continue}const k=key(w.a,w.b);if(seen.has(k))errors.push('重复导线：'+k);seen.add(k);if(a.id===b.id)errors.push(a.label+' 不能连接自身');else if(a.kind!==b.kind)errors.push(a.label+' → '+b.label+'：信号类型不匹配');else if(!expected.some(([a,b])=>key(a,b)===k))errors.push('连接组合不属于本实验：'+k)}for(const [a,b]of expected)if(!seen.has(key(a,b)))errors.push('缺少连接：'+a+' → '+b);return{ok:!errors.length,errors,complete:expected.filter(([a,b])=>seen.has(key(a,b))).length}}
const bands=[['LF','125 kHz','短距身份识别'],['HF','13.56 MHz','存储卡教学'],['UHF','860–960 MHz','批量物流标签'],['MICROWAVE','2.45 GHz','有源标签场景'],['NFC','13.56 MHz','近场读写 / 点对点']];
function initial(){return{wires:[],selected:null,band:'HF',memory:Array(16).fill('00000000'),access:'A1B2C3D4',authenticated:false,locked:false,rfidLog:[],wireLog:[],readerCount:1,slots:4}}
function memoryAction(state,action,d={}){const s=cp(state),log=msg=>s.rfidLog.unshift({at:new Date().toISOString(),band:s.band,message:msg});if(action==='auth'){if(d.password!==s.access)throw Error('教学访问口令不匹配');s.authenticated=true;log('教学认证成功（非真实射频认证）')}
else if(action==='read'||action==='write'){const block=Number(d.block);if(!Number.isInteger(block)||block<0||block>15)throw Error('块地址必须为 0–15');if(['HF','UHF','NFC'].includes(s.band)&&!s.authenticated)throw Error('当前频段实验需要先完成教学认证');if(action==='write'){if(s.band==='LF')throw Error('此 LF 教学标签设为只读');if(s.locked)throw Error('教学写保护已启用');if(!/^[0-9A-Fa-f]{8}$/.test(d.value||''))throw Error('数据必须为 8 位十六进制');s.memory[block]=d.value.toUpperCase();log('写入块 '+block+' = '+s.memory[block]);}else log('读取块 '+block+' = '+s.memory[block])}
else if(action==='lock'){if(!s.authenticated)throw Error('请先完成教学认证');s.locked=!s.locked;log(s.locked?'启用可逆教学写保护':'关闭教学写保护')}
else if(action==='band'){if(!bands.some(b=>b[0]===d.band))throw Error('未知频段');s.band=d.band;s.authenticated=false;log('切换频段，教学认证已清除')}
else if(action==='collision'){const readers=Number(d.readers),slots=Number(d.slots);if(!Number.isInteger(readers)||readers<1||readers>8||!Number.isInteger(slots)||slots<1||slots>8)throw Error('读写器和时隙须为 1–8 整数');s.readerCount=readers;s.slots=slots;s.assignment=Array.from({length:readers},(_,i)=>i%slots);const count={};s.assignment.forEach(x=>count[x]=(count[x]||0)+1);s.collisionSlots=Object.keys(count).filter(x=>count[x]>1).map(Number);log('时隙示例：'+readers+' 个读写器 / '+slots+' 个时隙；'+s.collisionSlots.length+' 个时隙冲突。简化共享信道模型，不代表射频性能')}
else throw Error('未知教学操作');s.rfidLog=s.rfidLog.slice(0,100);return s}
const helpers={pins,expected,bands,initial,validate,memoryAction};if(typeof module!=='undefined')module.exports=helpers;if(!root.document)return;let host,state,busy=false,chosen='',dragPin='',renderEpoch=0;const E=x=>root.escapeHTML(x),field=(l,n,v,type='text')=>`<label class="field">${l}<input name="${n}" type="${type}" value="${E(v)}"></label>`;
async function persist(next){busy=true;host.inert=true;try{await root.api('hardware_lab','POST',next);state=next;draw()}finally{busy=false;host.inert=false}}
async function wire(a,b){if(busy)return;if(a===b){chosen='';draw();return}if(!pins.some(p=>p.id===a)||!pins.some(p=>p.id===b))return;if(state.wires.some(w=>key(w.a,w.b)===key(a,b)))throw Error('该导线已存在');const s=cp(state);s.wires.push({a,b});chosen='';s.wireLog.unshift({at:new Date().toISOString(),message:'连接 '+a+' → '+b});await persist(s)}
function draw(){const check=validate(state.wires);host.innerHTML=`<div class="page-head"><div><div class="eyebrow">HARDWARE FUNDAMENTALS / 端子与射频实验</div><h1>接线与 RFID 存储实训</h1><p class="muted">实际编辑接线图、定位错线、操作教学标签存储区，保留实验记录</p></div><span class="badge gray">软件教学模型 · 无硬件连接</span></div><div class="workspace-split"><section class="card"><div class="section-title"><h2>端子接线画布</h2><span class="badge ${check.ok?'':'gray'}">${check.complete} / 4 正确连接</span></div><p class="muted">点击起点再点击终点，或将端子拖到另一个端子。点击导线删除。红线表示类型错误；本实验不评价真实接线安全。</p><svg id="wireCanvas" viewBox="0 0 620 350" style="width:100%;background:#f5f8fb;touch-action:none" role="img" aria-label="可编辑的电源和RS485接线图"><rect x="15" y="45" width="155" height="130" rx="5" fill="#e8eef6"/><rect x="15" y="205" width="155" height="130" rx="5" fill="#e8eef6"/><rect x="450" y="45" width="155" height="290" rx="5" fill="#e8eef6"/><text x="30" y="65" font-size="12" fill="#345778">24V 教学电源</text><text x="30" y="226" font-size="12" fill="#345778">RS485 教学网关</text><text x="465" y="65" font-size="12" fill="#345778">教学温度传感器</text>${state.wires.map((w,i)=>{const a=pins.find(p=>p.id===w.a),b=pins.find(p=>p.id===w.b);return`<line data-wire="${i}" x1="${a.x}" y1="${a.y}" x2="${b.x}" y2="${b.y}" stroke="${a.kind===b.kind?'#467da8':'#c74e44'}" stroke-width="5" style="cursor:pointer"><title>点击删除 ${E(w.a)} → ${E(w.b)}</title></line>`}).join('')}${pins.map(p=>`<g data-pin="${p.id}" tabindex="0" role="button" aria-label="${p.label}" style="cursor:crosshair"><circle cx="${p.x}" cy="${p.y}" r="12" fill="${chosen===p.id?'#d89434':'#2b628d'}" stroke="white" stroke-width="3"/><text x="${p.x<300?p.x+20:p.x-65}" y="${p.y+5}" font-size="11" fill="#3d5d7b">${p.id}</text></g>`).join('')}</svg><div class="toolbar" style="margin-top:16px"><button class="btn primary" id="wireCheck">验证接线</button><button class="btn" id="wireReset">清空接线</button><button class="btn" id="wireExport">导出实验配置</button><label class="btn">导入配置<input id="wireImport" type="file" accept=".json" style="width:165px"></label></div><div id="wireFeedback">${check.ok?'<p class="badge">四条必要连接正确。请继续在技术实训台设置协议。</p>':`<ul class="muted">${check.errors.map(e=>`<li>${E(e)}</li>`).join('')}</ul>`}</div></section><section class="card"><h2>元件认知与信号提示</h2><p><b>电源 +24V / GND</b><br><span class="muted">为教学传感器供电；正负端子不能交叉。</span></p><p><b>RS485 A / B</b><br><span class="muted">差分总线信号线。此题采用 A→A、B→B 命名规则，实际设备可能命名不同，必须阅读厂家接线图。</span></p><p><b>协议与接口不同</b><br><span class="muted">导线连接正确并不代表从站地址、波特率、校验位正确，后续协议实训仍需验证。</span></p><button class="btn" onclick="navigate('labs')">进入协议与入库实训</button><div class="divider"></div><h3>本次接线记录</h3>${state.wireLog.slice(0,6).map(l=>`<p class="muted">${E(l.message)}</p>`).join('')}</section></div><div class="grid two" style="margin-top:20px"><section class="card"><h2>RFID 存储与认证教学</h2><p class="muted">采用简化统一 16×4 字节内存模型。教学口令 A1B2C3D4 非真实卡密钥；不实现真实 S50 安全协议或 UHF Kill。</p><label class="field">射频场景<select id="rfidBand">${bands.map(([id,f,d])=>`<option value="${id}" ${state.band===id?'selected':''}>${id} · ${f} · ${d}</option>`).join('')}</select></label><form data-rfid="auth">${field('教学访问口令','password','','password')}<button class="btn">教学认证</button> <span class="badge ${state.authenticated?'':'gray'}">${state.authenticated?'已认证':'未认证'}</span></form><div class="divider"></div><form data-rfid="memory">${field('块地址 0–15','block',0,'number')}${field('数据：8 位十六进制','value','11223344')}<div class="toolbar"><button class="btn" type="submit" name="read">读取</button><button class="btn primary" type="submit" name="write">写入</button><button class="btn" id="rfidLock" type="button">${state.locked?'关闭':'开启'}教学写保护</button></div></form><table><thead><tr><th>块</th><th>内容</th><th>块</th><th>内容</th></tr></thead><tbody>${Array.from({length:8},(_,i)=>`<tr><td>${i}</td><td>${state.memory[i]}</td><td>${i+8}</td><td>${state.memory[i+8]}</td></tr>`).join('')}</tbody></table></section><section class="card"><h2>多读写器干扰教学</h2><p class="muted">多个读写器循环分配到有限时隙。相同时隙同时工作产生冲突，增加时隙可观察调度隔离效果。该简化模型不等价于真实射频防碰撞协议。</p><form data-rfid="collision">${field('读写器数量 1–8','readers',state.readerCount,'number')}${field('时隙数量 1–8','slots',state.slots,'number')}<button class="btn primary">计算并保存</button></form><div style="margin-top:20px">${(state.assignment||[]).map((slot,i)=>`<p><span class="badge ${(state.collisionSlots||[]).includes(slot)?'red':''}">读写器 ${i+1}</span> → 时隙 ${slot+1} ${(state.collisionSlots||[]).includes(slot)?'冲突':'独占'}</p>`).join('')}</div><h3>RFID 操作记录</h3><div style="max-height:300px;overflow:auto">${state.rfidLog.map(l=>`<div class="log-item"><span>${E(l.band)} · ${E(l.message)}</span><small>${new Date(l.at).toLocaleString('zh-CN')}</small></div>`).join('')||'<p class="muted">操作后显示真实教学事件。</p>'}</div></section></div>`;
const bind=(id,fn)=>host.querySelector('#'+id).onclick=()=>Promise.resolve().then(fn).catch(e=>root.toast(e.message));
host.querySelectorAll('[data-pin]').forEach(el=>{el.onclick=()=>{if(busy)return;const id=el.dataset.pin;if(chosen)wire(chosen,id).catch(e=>root.toast(e.message));else{chosen=id;draw()}};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.onclick()}};el.onpointerdown=()=>{dragPin=el.dataset.pin};el.onpointerup=()=>{if(dragPin&&dragPin!==el.dataset.pin){wire(dragPin,el.dataset.pin).catch(e=>root.toast(e.message));dragPin=''}}});
host.querySelectorAll('[data-wire]').forEach(el=>el.onclick=()=>{const s=cp(state);s.wires.splice(+el.dataset.wire,1);s.wireLog.unshift({at:new Date().toISOString(),message:'删除导线'});persist(s).catch(e=>root.toast(e.message))});
bind('wireCheck',()=>root.toast(check.ok?'接线验证通过':check.errors.join('；')));bind('wireReset',async()=>{if(!confirm('清空当前导线？RFID数据保留。'))return;const s=cp(state);s.wires=[];await persist(s)});bind('wireExport',()=>root.downloadJSON('hardware-teaching-lab.json',{schema:'hardware-lab/v1',data:state}));
host.querySelector('#wireImport').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error('文件超过 100KB');const x=JSON.parse(await f.text());if(x.schema!=='hardware-lab/v1'||!Array.isArray(x.data?.wires))throw Error('配置格式不匹配');const s=initial();s.wires=x.data.wires.map(w=>({a:String(w.a),b:String(w.b)}));if(s.wires.some(w=>!pins.some(p=>p.id===w.a)||!pins.some(p=>p.id===w.b)))throw Error('存在未知端子');validate(s.wires);if(Array.isArray(x.data.memory)&&x.data.memory.length===16&&x.data.memory.every(v=>/^[0-9A-F]{8}$/.test(v)))s.memory=x.data.memory;if(!confirm('导入接线和内存会覆盖当前实验，继续？'))return;await persist(s)}catch(e){root.toast(e.message)}};
host.querySelector('#rfidBand').onchange=e=>persist(memoryAction(state,'band',{band:e.target.value})).catch(e=>root.toast(e.message));host.querySelectorAll('form[data-rfid]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const op=f.dataset.rfid==='memory'?(e.submitter?.name||'read'):f.dataset.rfid;try{persist(memoryAction(state,op,Object.fromEntries(new FormData(f)))).catch(e=>root.toast(e.message))}catch(e){root.toast(e.message)}});bind('rfidLock',()=>persist(memoryAction(state,'lock')));
}
root.HardwareLab={helpers,async render(c){const epoch=++renderEpoch,data=await root.api('hardware_lab');if(epoch!==renderEpoch)return;host=c;state=data||initial();chosen='';draw()},async stop(){renderEpoch++;while(busy)await new Promise(r=>setTimeout(r,10))}};
})(typeof window!=='undefined'?window:globalThis);
